alter policy "agent reads own profile" on public.agent_personal_profiles using ((select public.is_izytel_firebase_jwt()) and firebase_uid = (select auth.jwt()->>'sub'));
alter policy "agent creates own profile" on public.agent_personal_profiles with check ((select public.is_izytel_firebase_jwt()) and firebase_uid = (select auth.jwt()->>'sub') and verification_status in ('incomplete','pending_review') and verification_note is null);
alter policy "agent updates own profile" on public.agent_personal_profiles using ((select public.is_izytel_firebase_jwt()) and firebase_uid = (select auth.jwt()->>'sub')) with check ((select public.is_izytel_firebase_jwt()) and firebase_uid = (select auth.jwt()->>'sub') and verification_status in ('incomplete','pending_review') and verification_note is null);
alter policy "agent reads own issues or staff reads all" on public.agent_issues using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_issue_staff())));
alter policy "agent creates own issue" on public.agent_issues with check ((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub') and status='open' and resolved_at is null and resolved_by is null and resolved_by_uid is null and legacy_firestore_id is null);
alter policy "finance staff creates suppliers" on public.finance_suppliers with check ((select private.is_izytel_finance_staff()) and created_by_uid = (select auth.jwt()->>'sub') and updated_by_uid = (select auth.jwt()->>'sub') and is_deleted=false);
alter policy "phase5 recharge owner or staff reads" on public.phase5_agent_recharges using (((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub')) or (select private.is_izytel_finance_staff()));
alter policy "phase5 ledger owner or staff reads" on public.phase5_ledger_events using (((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub')) or (select private.is_izytel_finance_staff()));
alter policy "phase5 proof owner or staff reads" on public.phase5_order_proofs using (((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub')) or (select private.is_izytel_agent_directory_staff()));
alter policy "agent inserts own order proofs" on public.phase5_order_proofs with check ((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub') and private.is_phase5_proof_owner(order_id));
alter policy "agent updates own order proofs" on public.phase5_order_proofs using ((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub') and private.is_phase5_proof_owner(order_id)) with check ((select public.is_izytel_firebase_jwt()) and agent_id = (select auth.jwt()->>'sub') and private.is_phase5_proof_owner(order_id));
alter policy "phase5 capacity own or staff read" on public.phase5_agent_capacities using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
alter policy "phase5 movements own or staff read" on public.phase5_network_movements using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
alter policy "phase5 finalizations own or staff read" on public.phase5_success_finalizations using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
alter policy "phase5 commissions own or staff read" on public.phase5_commissions using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
alter policy "phase5 commission accounts own or staff read" on public.phase5_commission_accounts using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
alter policy "phase5 commission payouts own or staff read" on public.phase5_commission_payouts using ((select public.is_izytel_firebase_jwt()) and (agent_id = (select auth.jwt()->>'sub') or (select private.is_izytel_finance_staff())));
